import { OrderKey, OrderRepository } from './repository';
import { ListRequest, Page } from './types';

function parseCursor(cursor: unknown): OrderKey {
  if (typeof cursor !== 'string') throw new Error('invalid request');
  const parts = cursor.split('|');
  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') throw new Error('invalid request');
  return { createdAt: parts[0], id: parts[1] };
}

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      throw new Error('invalid request');
    }
    const after = request.cursor === undefined ? undefined : parseCursor(request.cursor);
    // Fetch one extra matching row to learn whether a further page exists.
    const matches = this.repository.listAfter(request.tenant, after);
    const items = matches.slice(0, request.limit);
    const nextCursor = matches.length > request.limit
      ? `${items[items.length - 1].createdAt}|${items[items.length - 1].id}`
      : null;
    return { items, nextCursor };
  }
}
